style.css:
@-moz-document domain("roblox.com") {
/* GLOBAL — remove all backgrounds so your image shows */
body, html {
    background: #ffffff !important;   /* Pure white */
    color: #000000 !important;        /* Standard black text */
    font-family: "Inter", "Roboto", sans-serif !important;
}

/* Transparent backgrounds where possible */
.rbx-navbar,
.navbar-container,
.v2-avatar-card-container,
.card-item,
.game-card,
#navigation-container,
#advertisement,
.content,
.container,
.PageContent,
footer,
.banner-container,
.section-content,
#avatar-container,
.games-list,
.game-cards,
.universal-app-banner,
#HomeContainer,
#profile-header,
.friends-content,
.section {
    background: transparent !important;
    border: none !important;
}

/* Buttons – simple black text, grey outline */
.btn-primary, 
.rbx-btn-primary,
.btn-default,
.rbx-btn-default {
    background: #ffffff !important;
    color: #000000 !important;
    border: 1px solid #d0d0d0 !important;
    box-shadow: none !important;
}

.btn-primary:hover, 
.rbx-btn-primary:hover {
    background: #f2f2f2 !important;
}

/* Inputs */
input, textarea, select {
    background: #ffffff !important;
    color: #000000 !important;
    border: 1px solid #d0d0d0 !important;
}

/* Links */
a {
    color: #000000 !important;
    text-decoration: underline !important;
}

/* Remove shadows everywhere */
* {
    box-shadow: none !important;
}

/* Scrollbar — clean grey */
::-webkit-scrollbar {
    width: 12px;
}
::-webkit-scrollbar-track {
    background: #ffffff !important;
}
::-webkit-scrollbar-thumb {
    background: #cfcfcf !important;
    border-radius: 6px;
}
::-webkit-scrollbar-thumb:hover {
    background: #bfbfbf !important;
}
}
